import React, { useState, useEffect, useRef } from 'react';
import { Send, User as UserIcon, Loader2, MessageSquare, Phone } from 'lucide-react';
import { sendMessageApi, getConversationApi } from '../services/messageService';

export default function MessagesPage() {
  const currentUserId = 1; // বর্তমান লগইন ইউজার
  const selectedRecipientId = 2; // যাকে মেসেজ পাঠানো হচ্ছে (টেস্টের জন্য)

  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const messagesEndRef = useRef(null);

  const fetchConversation = async () => {
    try {
      const data = await getConversationApi(currentUserId, selectedRecipientId);
      setMessages(data);
    } catch (err) {
      console.error('মেসেজ লোড করতে সমস্যা:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchConversation();
    const interval = setInterval(fetchConversation, 3000); // ৩ সেকেন্ড পর পর অটো রিফ্রেশ
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async (e) => {
    e.preventDefault();
    if (!newMessage.trim()) return;

    setSending(true);
    try {
      await sendMessageApi(currentUserId, selectedRecipientId, newMessage);
      setNewMessage('');
      await fetchConversation();
    } catch (err) {
      console.error('মেসেজ পাঠাতে সমস্যা:', err);
    } finally {
      setSending(false);
    }
  };

  return (
    <div className="max-w-xl mx-auto px-4 py-4 h-[calc(100vh-100px)] flex flex-col">
      {/* Header */}
      <div className="bg-white rounded-2xl p-4 border border-slate-100 shadow-sm flex items-center justify-between mb-3 shrink-0">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-rose-50 border border-rose-100 flex items-center justify-center font-bold text-brand-600">
            A+
          </div>
          <div>
            <h2 className="text-sm font-black text-slate-900">রাকিব হাসান (রক্তদাতা)</h2>
            <p className="text-[11px] font-semibold text-emerald-600 flex items-center gap-1">
              <span className="w-2 h-2 rounded-full bg-emerald-500"></span> অনলাইনে আছেন
            </p>
          </div>
        </div>
        <a href="tel:01700000000" className="bg-slate-100 hover:bg-slate-200 text-slate-700 p-2.5 rounded-xl transition">
          <Phone className="w-4 h-4" />
        </a>
      </div>

      {/* Messages Box */}
      <div className="flex-1 bg-white rounded-3xl border border-slate-100 p-4 overflow-y-auto space-y-3 shadow-sm">
        {loading ? (
          <div className="flex justify-center py-10">
            <Loader2 className="w-6 h-6 text-brand-600 animate-spin" />
          </div>
        ) : messages.length === 0 ? (
          <div className="text-center py-12 space-y-2">
            <MessageSquare className="w-8 h-8 text-slate-300 mx-auto" />
            <p className="text-xs text-slate-400 font-bold">কথোপকথন শুরু করতে মেসেজ পাঠান</p>
          </div>
        ) : (
          messages.map((msg) => {
            const isMe = msg.senderId === currentUserId;
            return (
              <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
                <div
                  className={`max-w-[80%] px-4 py-2.5 rounded-2xl text-xs font-medium ${
                    isMe
                      ? 'bg-brand-600 text-white rounded-br-none shadow-sm'
                      : 'bg-slate-100 text-slate-800 rounded-bl-none'
                  }`}
                >
                  <p>{msg.content}</p>
                </div>
              </div>
            );
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Input Box */}
      <form onSubmit={handleSend} className="mt-3 flex items-center gap-2 shrink-0">
        <input
          type="text"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          placeholder="মেসেজ লিখুন..."
          className="flex-1 px-4 py-3 rounded-2xl border border-slate-200 text-xs font-medium focus:outline-none focus:border-brand-600 bg-white shadow-sm"
        />
        <button
          type="submit"
          disabled={sending || !newMessage.trim()}
          className="bg-brand-600 hover:bg-brand-700 text-white p-3 rounded-2xl shadow-lg shadow-brand-600/30 transition disabled:opacity-50"
        >
          {sending ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
        </button>
      </form>
    </div>
  );
}
